    function testFuzz_property(address caller, address to, uint256 v) public {
        vm.assume(to != address(0));
        address[] memory tos = new address[](1);
        tos[0] = to;
        uint[] memory vals = new uint[](1);
        vals[0] = v;

        bool ok;
        vm.prank(caller);
        try c.transfer(tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == (caller == c.from()));
    }
}
